Z = r"\mathbb{Z}"

D4 = [
dict(id="hawaii", n="Hawaiian earring", sym=r"\mathbb{H}=\bigcup_n C_n", cat="Pathological spaces",
 d=r"Circles $C_n$ of radius $1/n$ centered at $(1/n,0)$, with the subspace topology from $\mathbb{R}^2$.",
 p=[1,1,1,1,0,None,0,0], pi=r"\text{uncountable, not free}", H=rf"{Z},\ \text{{uncountable}},\dots", chi=r"\text{undefined}",
 how="No clean method: van Kampen and covering space theory both fail at the origin.",
 why=r"The standard example where computing $\pi_1$ is hard. It has no universal cover. Compare the infinite wedge of circles.",
 ps=[("Compact", "Closed and bounded in $\\mathbb{R}^2$. This is the difference from the CW wedge, whose topology is finer."),
     ("Not semilocally simply connected", "Every neighborhood of the origin contains all $C_n$ for large $n$. The retraction $r_n:\\mathbb{H}\\to C_n$ that collapses the other circles shows $C_n$ is not null-homotopic in $\\mathbb{H}$. So small loops at the origin are never trivial, and $\\mathbb{H}$ has no simply connected cover.")],
 alg=[("Retractions", "Collapsing $C_{n+1},C_{n+2},\\dots$ retracts $\\mathbb{H}$ onto the finite wedge $\\bigvee_{i\\le n}C_i$. These give compatible surjections $\\pi_1(\\mathbb{H})\\to F_n$ and a homomorphism $\\pi_1(\\mathbb{H})\\to\\varprojlim F_n$, which is injective but not surjective."),
      ("Uncountable", "A loop can run around $C_1$ in time $[0,\\frac12]$, $C_2$ in $[\\frac12,\\frac34]$, and so on, and still be continuous at $t=1$ because the circles shrink. Choosing which circles to traverse gives $2^{\\aleph_0}$ loops with distinct images in $\\varprojlim F_n$."),
      ("Not free", "Every finitely generated subgroup is free, but the whole group is not (Higman). $H_1$, the abelianization, is uncountable.")]),

dict(id="warsaw", n="Warsaw circle", sym=r"W", cat="Pathological spaces",
 d="The closed topologist's sine curve with its two ends joined by an arc.",
 p=[1,1,1,1,0,None,1,0], pi="1", H=rf"{Z},\ 0,\ 0,\dots", chi="1",
 how="A path cannot pass through the oscillating part, so every map of a sphere misses a point and lands in something contractible.",
 why=r"All homotopy groups vanish but $W$ is not contractible, so Whitehead's theorem needs the CW hypothesis. Čech cohomology sees the circle: $\check H^1(W)\cong\mathbb{Z}$.",
 ps=[("Compact, path-connected", "Closed and bounded in $\\mathbb{R}^2$. The extra arc joins the limit segment to the end of the curve, so it is path-connected, unlike the sine curve."),
     ("Not locally connected", "Near a point of the limit segment, every small ball meets infinitely many separate pieces of the oscillating curve.")],
 alg=[("Paths cannot go around", "No path travels from the limit segment into the oscillating curve, for the same reason the topologist's sine curve is not path-connected. So the compact image of any $S^k\\to W$ omits some point $p$ of the oscillating part."),
      ("Weakly contractible", "Each path component of $W\\setminus\\{p\\}$ is contractible, and the image of a sphere lies in one of them, so every map $S^k\\to W$ is null-homotopic. All $\\pi_k(W)=0$, and the map to a point is a weak equivalence, so singular homology is that of a point."),
      ("Not contractible", "$W$ is the intersection of nested annular neighborhoods, so its Čech cohomology is $\\check H^1(W)=\\varinjlim\\check H^1(\\text{annulus})=\\mathbb{Z}$. Čech cohomology is a homotopy invariant and vanishes on contractible spaces.")]),

dict(id="sine", n="Topologist's sine curve", sym=r"\overline{\{(x,\sin\tfrac1x):0<x\le1\}}", cat="Pathological spaces",
 d=r"The graph together with the limit segment $\{0\}\times[-1,1]$.",
 p=[1,1,0,1,0,None,None,0], pi=r"1\ \text{(each path component)}", H=rf"{Z}^2,\ 0,\dots", chi="2",
 how="Two path components, each contractible.",
 why=r"Connected but not path-connected. Singular $H_0$ counts path components, not components.",
 ps=[("Compact, connected", "It is the closure of the graph, a connected set, and closures of connected sets are connected. Closed and bounded, so compact."),
     ("Not path-connected", "Suppose $\\gamma$ is a path from $(0,0)$ to a point of the graph. Let $t_0$ be the last time $\\gamma$ is on the segment. Just after $t_0$ the $x$-coordinate is positive and tends to $0$, so the $y$-coordinate $\\sin(1/x)$ takes both values $\\pm1$ in every interval $(t_0,t_0+\\delta)$. This contradicts continuity of $\\gamma$ at $t_0$.")],
 alg=[("Homology", "The path components are the graph $\\cong(0,1]$ and the segment $\\cong[-1,1]$, both contractible. Singular homology is the direct sum over path components: $H_0=\\mathbb{Z}^2$, the rest zero. $\\chi=2$.")]),

dict(id="comb", n="Comb space", sym=r"C", cat="Pathological spaces",
 d=r"The base $[0,1]\times\{0\}$ with vertical unit teeth at $x=0$ and at each $x=1/n$.",
 p=[1,1,1,1,0,None,1,1], pi="1", H=rf"{Z},\ 0,\dots", chi="1",
 how="Slide the teeth down to the base, then contract the base.",
 why=r"Contractible but not locally connected, and it does not deformation retract onto $(0,1)$ while keeping that point fixed.",
 ps=[("Compact", "Closed and bounded: the teeth at $1/n$ accumulate on the tooth at $0$, which is included."),
     ("Not locally connected", "A small ball around $(0,y)$ with $y>0$ meets infinitely many teeth in disjoint segments.")],
 alg=[("Contraction", "First $H((x,y),t)=(x,(1-t)y)$ for $t\\in[0,1]$, which slides every tooth down along itself; then contract $[0,1]\\times\\{0\\}$ to a point."),
      ("No strong deformation retraction to $(0,1)$", "During such a homotopy, points $(1/n,1)$ near $(0,1)$ must stay near $(0,1)$ for small times, but to reach it they must travel down their tooth and along the base. Continuity at $(0,1)$ fails.")]),

dict(id="solenoid", n="Dyadic solenoid", sym=r"\Sigma_2=\varprojlim\big(S^1\xleftarrow{z^2}S^1\xleftarrow{z^2}\cdots\big)", cat="Pathological spaces",
 d="The inverse limit of circles under the doubling map; a compact connected abelian group.",
 p=[1,1,0,1,0,None,None,0], pi=r"1\ \text{(each path component)}", H=rf"H_0\cong\bigoplus_{{2^{{\aleph_0}}}}{Z}", chi=r"\text{undefined}",
 how=r"Path components are dense continuous images of $\mathbb{R}$, uncountably many.",
 why=r"Connected with uncountably many path components. Čech cohomology $\check H^1\cong\mathbb{Z}[1/2]$ records the inverse limit; singular theory does not.",
 ps=[("Compact, Hausdorff", "A closed subset of the compact metrizable product $\\prod S^1$."),
     ("Connected", "An inverse limit of compact connected Hausdorff spaces is connected."),
     ("Locally a Cantor set times an interval", "A small neighborhood looks like an arc times the 2-adic integers, so the space is not locally connected.")],
 alg=[("Path components", "$t\\mapsto(e^{2\\pi it},e^{\\pi it},e^{\\pi it/2},\\dots)$ maps $\\mathbb{R}$ injectively onto the path component of the identity. The other path components are its cosets, and there are $2^{\\aleph_0}$ of them."),
      ("Čech cohomology", "Čech cohomology turns inverse limits of compact spaces into direct limits: $\\check H^1(\\Sigma_2)=\\varinjlim(\\mathbb{Z}\\xrightarrow{2}\\mathbb{Z}\\xrightarrow{2}\\cdots)=\\mathbb{Z}[1/2]$.")]),

dict(id="cantor", n="Cantor set", sym=r"C\cong\{0,1\}^{\mathbb{N}}", cat="Pathological spaces",
 d=r"Middle thirds removed from $[0,1]$, forever.",
 p=[1,0,0,1,0,None,None,0], pi=r"1\ \text{(at each point)}", H=rf"H_0\cong\bigoplus_{{2^{{\aleph_0}}}}{Z}", chi=r"\text{undefined}",
 how="Totally disconnected, so every path is constant.",
 why="Compact, perfect, totally disconnected, and metrizable. Every compact metric space is a continuous image of it.",
 ps=[("Compact", "An intersection of closed subsets of $[0,1]$."),
     ("Totally disconnected", "Between two points of $C$ there is a removed open interval. Splitting at it writes $C$ as a union of two disjoint clopen sets separating the points."),
     ("Perfect", "Every point is a limit of endpoints of the construction."),
     ("Product model", "Ternary expansions with digits $0,2$ give a homeomorphism $C\\to\\{0,2\\}^{\\mathbb{N}}$.")],
 alg=[("Homology", "A path has connected image, which must be a point. Singular simplices are constant, so the chain complex is a direct sum of copies of that of a point, one for each element of $C$.")]),

dict(id="longline", n="Long line", sym=r"L=\omega_1\times[0,1)", cat="Pathological spaces",
 d="Uncountably many unit intervals glued end to end, with the lexicographic order topology.",
 p=[0,1,1,1,0,None,1,0], pi="1", H=rf"{Z},\ 0,\dots", chi="1",
 how="Every compact subset lies in a countable initial segment, which is an interval.",
 why="Locally Euclidean and Hausdorff but not second countable. All homotopy groups vanish, yet it is not contractible.",
 ps=[("Connected", "A linearly ordered set with the least upper bound property and no gaps is connected in the order topology."),
     ("Locally Euclidean, not second countable", "Each point has a neighborhood order-isomorphic to an open interval. The open intervals $(\\alpha\\times\\{\\frac12\\},(\\alpha+1)\\times\\{\\frac12\\})$ form an uncountable disjoint family, which a countable base cannot accommodate."),
     ("Not compact, not metrizable", "It is sequentially compact, since every countable set is bounded, but not compact: the initial segments cover it with no finite subcover. A metric space that is sequentially compact is compact, so $L$ is not metrizable.")],
 alg=[("Homotopy groups", "A countable ordinal $\\alpha$ gives an initial segment $[0,\\alpha]\\cong[0,1]$. Every compact image of a sphere lies in such a segment, so it is null-homotopic."),
      ("Not contractible", "A contraction would be a homotopy $L\\times[0,1]\\to L$. An argument with closed unbounded subsets of $\\omega_1$ shows this is impossible.")]),

dict(id="rationals", n="Rationals", sym=r"\mathbb{Q}", cat="Pathological spaces",
 d=r"Subspace topology from $\mathbb{R}$.",
 p=[0,0,0,1,0,None,None,0], pi=r"1\ \text{(at each point)}", H=rf"H_0\cong\bigoplus_{{\mathbb{{N}}}}{Z}", chi=r"\text{undefined}",
 how="Totally disconnected.",
 why=r"Not locally compact. Every countable metric space with no isolated points is homeomorphic to $\mathbb{Q}$ (Sierpiński).",
 ps=[("Totally disconnected", "For rationals $p<q$ pick an irrational $r$ between them; $(-\\infty,r)\\cap\\mathbb{Q}$ is clopen."),
     ("Not locally compact", "The closure in $\\mathbb{Q}$ of any interval $(a,b)\\cap\\mathbb{Q}$ contains sequences converging to irrationals, which have no convergent subsequence in $\\mathbb{Q}$.")],
 alg=[("Homology", "Paths are constant, so $H_0$ is free on the countably many points and the rest vanishes.")]),

dict(id="sorgenfrey", n="Sorgenfrey line", sym=r"\mathbb{R}_\ell", cat="Pathological spaces",
 d=r"$\mathbb{R}$ with basis the half-open intervals $[a,b)$.",
 p=[0,0,0,1,0,None,None,0], pi=r"1\ \text{(at each point)}", H=rf"H_0\cong\bigoplus_{{2^{{\aleph_0}}}}{Z}", chi=r"\text{undefined}",
 how=r"Totally disconnected: $[a,b)$ is clopen.",
 why=r"Normal and Lindelöf, but $\mathbb{R}_\ell\times\mathbb{R}_\ell$ is not normal. Separable and first countable but not second countable.",
 ps=[("Totally disconnected", "$[a,b)$ is open, and its complement $(-\\infty,a)\\cup[b,\\infty)$ is a union of basic sets, so $[a,b)$ is also closed."),
     ("Countability", "$\\mathbb{Q}$ is dense and $[x,x+\\frac1n)$ is a countable local base. Any base must contain, for each $x$, a set with minimum $x$, so it is uncountable."),
     ("The Sorgenfrey plane", "The antidiagonal $\\{(x,-x)\\}$ is closed and discrete in $\\mathbb{R}_\\ell^2$ and has size $2^{\\aleph_0}$. Jones' lemma then shows the separable space $\\mathbb{R}_\\ell^2$ is not normal.")],
 alg=[("Homology", "Connected subsets are points, so paths are constant and $H_0$ is free on $2^{\\aleph_0}$ generators.")]),

dict(id="twoorigins", n="Line with two origins", sym=r"\mathbb{R}\sqcup\mathbb{R}/(x\sim x,\ x\ne0)", cat="Non-Hausdorff and finite spaces",
 d=r"Two copies of $\mathbb{R}$ glued everywhere except at $0$.",
 p=[0,1,1,0,0,None,0,0], pi=Z, H=rf"{Z},\ {Z},\ 0", chi="0",
 how="The two copies of $\\mathbb{R}$ overlap in two pieces, which creates a loop.",
 why="Locally Euclidean and second countable; only Hausdorff fails, and that alone produces $\\pi_1\\cong\\mathbb{Z}$.",
 ps=[("Locally Euclidean, second countable", "Each copy of $\\mathbb{R}$ is open and is a chart."),
     ("Not Hausdorff", "Every neighborhood of $0_1$ and every neighborhood of $0_2$ contain $(-\\varepsilon,\\varepsilon)\\setminus\\{0\\}$ for some $\\varepsilon$, so they meet.")],
 alg=[("A loop", "Go from $1$ to $0_1$ to $-1$ in the first copy, then from $-1$ to $0_2$ to $1$ in the second copy. This loop is not null-homotopic."),
      ("Mayer–Vietoris", "Use $U,V$ the two copies, each contractible, with $U\\cap V=\\mathbb{R}\\setminus\\{0\\}$, two contractible pieces. Mayer–Vietoris holds for open covers of any space: $0\\to H_1(X)\\to H_0(U\\cap V)$ $\\to H_0(U)\\oplus H_0(V)\\to H_0(X)\\to0$, where $H_0(U\\cap V)=\\mathbb{Z}^2$ and $H_0(U)\\oplus H_0(V)=\\mathbb{Z}^2$. The middle map is $(x,y)\\mapsto(x+y,-x-y)$, with kernel $\\mathbb{Z}$. So $H_1=\\mathbb{Z}$."),
      ("Fundamental group", "The groupoid form of van Kampen gives $\\pi_1=\\mathbb{Z}$; the space is weakly equivalent to $S^1$.")]),

dict(id="pseudocircle", n="Pseudocircle", sym=r"\mathbb{S}=\{a,b,c,d\}", cat="Non-Hausdorff and finite spaces",
 d=r"Four points; open sets generated by $\{a\},\{b\},\{a,b,c\},\{a,b,d\}$.",
 p=[1,1,1,0,0,None,0,0], pi=Z, H=rf"{Z},\ {Z},\ 0", chi="0",
 how=r"McCord: a finite $T_0$ space is weakly equivalent to the order complex of its poset, here a 4-cycle.",
 why=r"A four-point space with $\pi_1\cong\mathbb{Z}$. Every finite simplicial complex is weakly equivalent to a finite space.",
 ps=[("Path-connected", "$\\gamma(0)=c$, $\\gamma(t)=a$ for $t>0$ is continuous: the preimage of each open set is $\\emptyset$, $(0,1]$, or $[0,1]$. Similar paths join every pair of points."),
     ("$T_0$, not $T_1$", "$\\{a\\}$ is not closed, since its complement $\\{b,c,d\\}$ is not open. Distinct points are distinguished by some open set.")],
 alg=[("Van Kampen picture", "$U=\\{a,b,c\\}$ and $V=\\{a,b,d\\}$ are open and contractible (each contracts onto its closed point $c$ or $d$). $U\\cap V=\\{a,b\\}$ is discrete with two points. This is the same pattern as the line with two origins, so $\\pi_1=\\mathbb{Z}$ and $H_1=\\mathbb{Z}$."),
      ("Order complex", "The specialization order has $a,b<c$ and $a,b<d$. The order complex has vertices $a,b,c,d$ and edges $ac,ad,bc,bd$, a square, which is a circle.")]),

dict(id="sierpinski", n="Sierpiński space", sym=r"\{0,1\},\ \text{open sets }\emptyset,\{1\},\{0,1\}", cat="Non-Hausdorff and finite spaces",
 d="Two points, one open and one closed.",
 p=[1,1,1,0,0,None,1,1], pi="1", H=rf"{Z},\ 0,\dots", chi="1",
 how="Contract everything to the open point at once.",
 why=r"$T_0$ but not $T_1$. Continuous maps from $X$ to it correspond to open subsets of $X$.",
 ps=[("Not $T_1$", "$\\{1\\}$ is not closed."),
     ("Classifies open sets", "$f:X\\to\\{0,1\\}$ is continuous iff $f^{-1}(1)$ is open.")],
 alg=[("Contraction", "$H(x,0)=x$ and $H(x,t)=1$ for $t>0$. The preimage of $\\{1\\}$ is $(\\{0,1\\}\\times(0,1])\\cup(\\{1\\}\\times[0,1])$, which is open, so $H$ is continuous.")]),

dict(id="cofinite", n="Countable cofinite space", sym=r"(\mathbb{N},\ \text{cofinite})", cat="Non-Hausdorff and finite spaces",
 d=r"Open sets are $\emptyset$ and complements of finite sets.",
 p=[1,1,0,0,0,None,None,0], pi=r"1\ \text{(at each point)}", H=rf"H_0\cong\bigoplus_{{\mathbb{{N}}}}{Z}", chi=r"\text{undefined}",
 how=r"Sierpiński's theorem forces every path to be constant.",
 why=r"$T_1$, compact, connected, but not path-connected. On an uncountable set such as $\mathbb{R}$ the cofinite topology is path-connected.",
 ps=[("Compact", "Any nonempty open set misses only finitely many points, which finitely many more sets cover."),
     ("$T_1$, not Hausdorff, connected", "Points are closed. Two nonempty open sets have finite complements in an infinite set, so they intersect; in particular no separation exists."),
     ("Not path-connected", "For a path $\\gamma:[0,1]\\to\\mathbb{N}$, the fibers $\\gamma^{-1}(n)$ are disjoint closed sets covering $[0,1]$, countably many. Sierpiński's theorem: a compact connected Hausdorff space is not a countable union of two or more disjoint nonempty closed sets. So one fiber is everything and $\\gamma$ is constant."),
     ("Uncountable case", "On $\\mathbb{R}$, any injection $[0,1]\\to\\mathbb{R}$ is continuous for the cofinite topology, since preimages of finite sets are finite and hence closed.")],
 alg=[("Homology", "Paths are constant, so $H_0$ is free on the points and the rest vanishes.")]),
]
